-- PROJECTS-SPR-602 migration (Founder Directive: Projects & Opportunities
-- Canonical Product) — creates the "ecosystems" table backing the new
-- Ecosystem CRUD in Admin, which now manages /portal/duan-cohoi (Canonical
-- Product) directly. Replaces the old digital_asset_projects/digital_asset_links
-- model (Consumer = 0 on the real Portal — only served the dead
-- /portal/digital-assets/** route).
--
-- QUAN TRỌNG: phải chạy script này trong Supabase SQL Editor TRƯỚC KHI merge
-- nhánh này vào Production. Nếu chưa chạy, /portal/duan-cohoi sẽ hiển thị
-- rỗng (bảng "ecosystems" chưa tồn tại → fetch API trả lỗi → Portal nhận
-- mảng rỗng, xem src/lib/admin/store.ts useSupabaseCollection). Nhánh này
-- chưa deploy Production (theo đúng "Không merge. Không deploy.").

create table if not exists ecosystems (
  id text primary key,
  data jsonb not null default '{}'::jsonb,
  status text not null default 'Draft',
  "order" int not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table ecosystems enable row level security;
drop policy if exists "public read published" on ecosystems;
create policy "public read published" on ecosystems for select using (status in ('Published', 'Active'));

insert into ecosystems (id, data, status, "order") values
  ('eco_digiu', '{"id":"eco_digiu","slug":"digiu","articleCategory":"digiu","name":"Hệ sinh thái DigiU","icon":"layers","colorKey":"blue","shortDescription":"Nền tảng học và kiếm thu nhập số — mình đang đồng hành và chia sẻ trải nghiệm thực tế.","fullIntro":"DigiU là hệ sinh thái sản phẩm số mình đang trực tiếp đồng hành và quan sát, không phải một khoá học đã hoàn thiện. Trang này gom lại đúng những gì mình biết chắc tới hiện tại — không tô vẽ thêm để trông hấp dẫn hơn thực tế.","highlights":["Đang trong giai đoạn mình trực tiếp theo dõi và sử dụng, chưa phải đánh giá dài hạn.","Nội dung chia sẻ tại đây là trải nghiệm cá nhân, không phải tài liệu chính thức của DigiU."],"statusBadge":"Đang theo dõi","whoFor":"Người mới muốn bắt đầu kiếm thu nhập số, chấp nhận vài tháng đầu chưa có kết quả rõ ràng.","whoNotReady":"Người cần thu nhập ngay lập tức, hoặc chưa từng dùng công cụ AI cơ bản nào.","expectedOutcome":"Kỹ năng vận hành một kênh nội dung số bằng AI — không phải cam kết thu nhập cụ thể.","structureType":"sub-projects","links":[{"id":"link_digiu_main","label":"Đăng ký / đăng nhập DigiU","url":"https://lk.digiu.ai/auth/registration/6845205668","order":1,"visible":true}],"subProjects":[{"id":"sub_digiu_alphamind","slug":"alphamind","name":"Khoá học Alphamind","shortDescription":"Một sản phẩm học trong hệ sinh thái DigiU — đăng ký qua cùng cổng tài khoản DigiU.","colorIndex":0,"links":[{"id":"link_alphamind","label":"Đăng ký Khoá học Alphamind","url":"https://lk.digiu.ai/auth/registration/6845205668","order":1,"visible":true}]},{"id":"sub_digiu_webwisepay","slug":"webwisepay","name":"Mở thẻ WebWisePay","shortDescription":"Sản phẩm thẻ trong hệ sinh thái DigiU — đăng ký qua Telegram bot riêng.","colorIndex":1,"links":[{"id":"link_webwisepay","label":"Mở thẻ WebWisePay (Telegram)","url":"https://t.me/WebWisePay_bot?start=ref_49419218-1eac-4683-ab3e-74a7ca266da0","order":1,"visible":true}]},{"id":"sub_digiu_deposits","slug":"deposits","name":"Mở khoản tiền gửi (Deposit